mapper.select:
SELECT 
  FROM emp13_project
  JOIN emp01_person ON emp13_person_id = emp01_person_id
 WHERE emp01_company_id = #{companyId}
   AND emp13_person_id  = #{personId}
 ORDER BY emp13_fr_ym DESC

mapper.update:
UPDATE emp13_project
   SET emp13_fr_ym      = #{req.frYm}
     , emp13_to_ym      = #{req.toYm}
     , emp13_project_nm = #{req.projectNm}
     , emp13_note       = #{req.note}
 WHERE emp13_project_id = #{projectId}
   AND emp13_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )

mapper.delete:
DELETE FROM emp13_project
 WHERE emp13_project_id IN
#{id}
   AND emp13_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )
